function matchScore(j){const s=evaluate(j,state.profile);return {...s,total:s.score,role:s.parts.profession,skills:s.parts.stack,level:s.parts.level,geo:s.parts.geography}}
function baseJobs(){if(view==='favorites')return state.jobs.filter(j=>j.favorite);if(view==='today')return state.jobs.filter(j=>todayIds().has(j.id));if(view==='applications')return state.jobs.filter(j=>j.appliedAt||appliedStatuses.includes(j.status));if(view==='interviews')return state.jobs.filter(j=>activeStatuses.includes(j.status)||j.status==='offer'||j.events.length);return [...state.jobs];}
function filteredJobs(){let js=baseJobs();if(view==='jobs'||view==='today')js=js.filter(j=>!evaluate(j,state.profile).excluded);const ids=todayIds();for(const key of quickSet)js=js.filter(j=>passesQuick(j,key,state.profile,ids));const profession=$('#filter-profession').value;if(profession)js=js.filter(j=>evaluate(j,state.profile).profession===profession);const q=$('#search').value.trim().toLocaleLowerCase();if(q)js=js.filter(j=>[j.title,j.company,j.notes,j.nextAction,j.tags.join(' ')].join(' ').toLocaleLowerCase().includes(q));for(const field of ['role','format','country','status','priority','availability','match']){const v=$('#filter-'+field).value;if(v)js=js.filter(j=>j[field]===v)}const minScore=Number($('#filter-score').value||0);if(minScore)js=js.filter(j=>(matchScore(j)?.total||0)>=minScore);const freshFilter=$('#filter-fresh').value;if(freshFilter==='new')js=js.filter(j=>Date.now()-Date.parse(j.createdAt)<7*86400000);if(freshFilter==='soon')js=js.filter(j=>j.deadline&&j.deadline>=today()&&j.deadline<=plusDays(7));const sort=$('#sort').value;const rank={high:0,medium:1,low:2};return js.sort((a,b)=>sort==='strategy'?compareJobs(a,b,state.profile):sort==='score'?(matchScore(b)?.total||0)-(matchScore(a)?.total||0)||rank[a.priority]-rank[b.priority]:sort==='new'?b.createdAt.localeCompare(a.createdAt):sort==='company'?a.company.localeCompare(b.company):sort==='deadline'?(a.deadline||'9999').localeCompare(b.deadline||'9999'):rank[a.priority]-rank[b.priority]||b.createdAt.localeCompare(a.createdAt));}
function renderFilters(){const filters={role:roles,format:formats,country:[...new Set([...state.jobs.map(j=>j.country)])].sort(),status:statuses,priority:priorities,match:{core:'Для старта',adjacent:'Смежная роль',stretch:'На вырост'},availability:{open:'Открыта',closed:'Закрыта',unverified:'Нужна проверка',program:'Программа'}};for(const [f,opts]of Object.entries(filters)){const el=$('#filter-'+f),old=el.value,first=el.options[0].outerHTML;el.innerHTML=first+(Array.isArray(opts)?arrOptions(opts,old):options(opts,old));if([...el.options].some(o=>o.value===old))el.value=old;el.classList.toggle('is-active',!!el.value)}}
function startOfWeek(){const d=new Date(today()+'T00:00:00Z');const day=d.getUTCDay();d.setUTCDate(d.getUTCDate()-(day===0?6:day-1));return d.toISOString().slice(0,10)}
function renderStats(){const applied=state.jobs.filter(j=>j.appliedAt||appliedStatuses.includes(j.status));const active=state.jobs.filter(j=>activeStatuses.includes(j.status));const offers=state.jobs.filter(j=>j.status==='offer').length;const saved=state.jobs.filter(j=>['saved','preparing'].includes(j.status));const week=applied.filter(j=>j.appliedAt&&j.appliedAt>=startOfWeek()&&j.appliedAt<=today()).length;$('#stat-saved').textContent=saved.length;$('#stat-saved-detail').textContent=saved.length?`${saved.filter(j=>j.priority==='high').length} с высоким приоритетом`:'Время найти новые возможности';$('#stat-applied').textContent=applied.length;$('#stat-interviews').textContent=active.length;$('#stat-offers').textContent=offers?`Офферов получено: ${offers}`:'0 офферов · всё ещё впереди';$('#weekly-count').textContent=week;$('#weekly-bar').style.width=Math.min(week/5*100,100)+'%';$('#nav-jobs').textContent=state.jobs.length;$('#nav-favorites').textContent=state.jobs.filter(j=>j.favorite).length;$('#nav-today').textContent=todayIds().size;$('#nav-applications').textContent=applied.length;$('#nav-interviews').textContent=state.jobs.filter(j=>activeStatuses.includes(j.status)||j.status==='offer'||j.events.length).length;}
function companyClass(j){return j.company.startsWith('Canonical')?'canonical':j.company==='MixRank'?'mixrank':j.company.includes('Onbrane')?'onbrane':j.company==='Andersen'?'andersen':''}
