function statusSelect(j){return `<select class="status-select" data-status="${esc(j.id)}" aria-label="Статус ${esc(j.title)} в ${esc(j.company)}">${options(statuses,j.status)}</select>`}
function priorityBadge(j){return `<div class="card-rank">${scoreBadge(j)}<button class="priority ${esc(j.priority)}" data-priority="${esc(j.id)}" title="Изменить приоритет" aria-label="Приоритет ${esc(j.title)}: ${esc(priorities[j.priority])}">${icon('flag')}${esc(priorities[j.priority])}</button></div>`}
